=head2 Google::Cloud::Backupdr::V1beta::Backupvault::CreateBackupVaultRequest

Message for creating a BackupVault.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->parent() >> / C<< $msg->parent($value) >>

Type: C<String>

Required. Value for parent.

=item * C<< $msg->backup_vault_id() >> / C<< $msg->backup_vault_id($value) >>

Type: C<String>

Required. ID of the requesting object
If auto-generating ID server-side, remove this field and
backup_vault_id from the method_signature of Create RPC

=item * C<< $msg->backup_vault() >> / C<< $msg->backup_vault($value) >>

Type: C<Message> (L<Google::Cloud::Backupdr::V1beta::Backupvault::BackupVault>)

Required. The resource being created

=item * C<< $msg->request_id() >> / C<< $msg->request_id($value) >>

Type: C<String>

Optional. An optional request ID to identify requests. Specify a unique
request ID so that if you must retry your request, the server will know to
ignore the request if it has already been completed. The server will
guarantee that for at least 60 minutes since the first request.

For example, consider a situation where you make an initial request and
the request times out. If you make the request again with the same request
ID, the server can check if original operation with the same request ID
was received, and if so, will ignore the second request. This prevents
clients from accidentally creating duplicate commitments.

The request ID must be a valid UUID with the exception that zero UUID is
not supported (00000000-0000-0000-0000-000000000000).

=item * C<< $msg->validate_only() >> / C<< $msg->validate_only($value) >>

Type: C<Bool>

Optional. Only validate the request, but do not perform mutations.
The default is 'false'.

=back

=head2 Google::Cloud::Backupdr::V1beta::Backupvault::ListBackupVaultsRequest

Request message for listing backupvault stores.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->parent() >> / C<< $msg->parent($value) >>

Type: C<String>

Required. The project and location for which to retrieve backupvault stores
information, in the format 'projects/{project_id}/locations/{location}'. In
Google Cloud Backup and DR, locations map to Google Cloud regions, for
example
B<us-central1>.
To retrieve backupvault stores for all locations, use "-" for the
'{location}' value.

=item * C<< $msg->page_size() >> / C<< $msg->page_size($value) >>

Type: C<Int32>

Optional. Requested page size. Server may return fewer items than
requested. If unspecified, server will pick an appropriate default.

=item * C<< $msg->page_token() >> / C<< $msg->page_token($value) >>

Type: C<String>

Optional. A token identifying a page of results the server should return.

=item * C<< $msg->filter() >> / C<< $msg->filter($value) >>

Type: C<String>

Optional. Filtering results.

=item * C<< $msg->order_by() >> / C<< $msg->order_by($value) >>

Type: C<String>

Optional. Hint for how to order the results.

=item * C<< $msg->view() >> / C<< $msg->view($value) >>

Type: C<Enum> (L<Google::Cloud::Backupdr::V1beta::BackupVaultView>)

Optional. Reserved for future use to provide a BASIC & FULL view of Backup
Vault.

=back

